local ALPHABET="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local bxor=(bit32 and bit32.bxor) or (bit and bit.bxor)

local function decode_bundle()
	local input=table.concat(ENCODED)
	local rank={}
	for index=1,#ALPHABET do rank[ALPHABET:sub(index,index)]=index-1 end
	local key_length=#DECODE_KEY
	local cache={}
	local output={}
	local cursor=0
	local group_index=0

	for position=1,#input,4 do
		group_index=group_index+1
		local character_one=input:sub(position,position)
		local character_two=input:sub(position+1,position+1)
		local character_three=input:sub(position+2,position+2)
		local character_four=input:sub(position+3,position+3)
		local phase=(((group_index-1)*3)%key_length)+1
		local cache_key=phase.."|"..character_one..character_two..character_three..character_four
		local decoded_group=cache[cache_key]

		if not decoded_group then
			local value_one=rank[character_one] or 0
			local value_two=rank[character_two] or 0
			local value_three=rank[character_three] or 0
			local value_four=rank[character_four] or 0
			local packed=value_one*262144+value_two*4096+value_three*64+value_four
			local byte_one=math.floor(packed/65536)%256
			local byte_two=math.floor(packed/256)%256
			local byte_three=packed%256
			byte_one=bxor(byte_one,DECODE_KEY:byte(phase))
			byte_two=bxor(byte_two,DECODE_KEY:byte((phase%key_length)+1))
			byte_three=bxor(byte_three,DECODE_KEY:byte(((phase+1)%key_length)+1))
			decoded_group=string.char(byte_one,byte_two,byte_three)
			cache[cache_key]=decoded_group
		end

		cursor=cursor+1
		output[cursor]=decoded_group
	end

	return table.concat(output):sub(1,EXPECTED_LENGTH)
end

local success,result=pcall(decode_bundle)
if not success or type(result)~="string" or #result~=EXPECTED_LENGTH then
	warn("[ENRIQUE] Runtime bundle failed integrity check.")
	return
end

local hash=0
for index=1,#result do hash=(hash*31+string.byte(result,index))%2147483647 end
if hash~=EXPECTED_HASH then
	warn("[ENRIQUE] Runtime bundle checksum mismatch.")
	return
end

local compiler=(loadstring or load)(result,"=ENRIQUE_PAID")
if not compiler then warn("[ENRIQUE] Unable to initialize protected runtime.") return end
local ok,error_message=pcall(compiler)
if not ok then warn("[ENRIQUE] "..tostring(error_message)) end
